ALTER TABLE "institutions" ADD CONSTRAINT "institutions_attendance_correction_days_check"
  CHECK ("attendance_correction_days" BETWEEN 0 AND 365);

-- (by hand) Row security: the same rule as every organization table
ALTER TABLE "attendance_records" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "attendance_records" FORCE ROW LEVEL SECURITY;
CREATE POLICY organization_isolation ON "attendance_records"
  USING (current_setting('app.bypass_rls', true) = 'on'
         OR "organization_id"::text = current_setting('app.organization_id', true))
  WITH CHECK (current_setting('app.bypass_rls', true) = 'on'
         OR "organization_id"::text = current_setting('app.organization_id', true));
